@dataclass(slots=True)
class OptimizerIdentityRunCache[T]:
    """Cache typed facts by exact object identity for one optimizer run."""

    _entries: dict[int, tuple[object, T]] = field(default_factory=dict)

    def get(self, owner: object) -> T | None:
        """Return the fact for the exact owner object."""
        cached = self._entries.get(id(owner))
        if cached is not None and cached[0] is owner:
            return cached[1]
        return None

    def set(self, owner: object, value: T) -> None:
        """Store one fact while retaining the exact owner object."""
        self._entries[id(owner)] = (owner, value)

    def get_or_create(self, owner: object, factory: Callable[[], T]) -> tuple[T, bool]:
        """Return an exact-owner fact and whether it was already cached."""
        cached = self._entries.get(id(owner))
        if cached is not None and cached[0] is owner:
            return cached[1], True
        value = factory()
        self.set(owner, value)
        return value, False

    def clear(self) -> None:
        """Evict all facts from this optimizer run cache."""
        self._entries.clear()


