@dataclass(slots=True)
class OptimizerRunCache:
    """Cache pure planning facts for one lower and optimize run.

    The pipeline entry point creates the instance. Each downstream phase
    requires that instance. Backends and connections must not own it.
    """

    strategy_probe_by_fingerprint: OptimizerStrategyProbeCache = field(default_factory=OptimizerStrategyProbeCache)
    strategy_probe_by_shape: OptimizerStrategyProbeCache = field(default_factory=OptimizerStrategyProbeCache)
    strategy_can_handle_by_fingerprint: OptimizerFactCache[bool] = field(default_factory=OptimizerFactCache)
    strategy_can_handle_by_shape: OptimizerFactCache[bool] = field(default_factory=OptimizerFactCache)
    step_scheduling_by_fingerprint: OptimizerFactCache["StepSchedulingFact"] = field(default_factory=OptimizerFactCache)
    static_step_scheduling_by_fingerprint: OptimizerFactCache["StepSchedulingFact"] = field(default_factory=OptimizerFactCache)
    plan_analysis_scheduling_by_template: OptimizerFactCache[tuple["StepSchedulingFact", ...]] = field(default_factory=OptimizerFactCache)
    legacy_adapter_scheduling_by_fingerprint: OptimizerFactCache["StepSchedulingFacts | None"] = field(default_factory=OptimizerFactCache)
    legacy_adapter_schema_by_fingerprint: OptimizerFactCache["RelationSchema"] = field(default_factory=OptimizerFactCache)
    legacy_adapter_access_by_identity: OptimizerAccessCache = field(default_factory=OptimizerAccessCache)
    analysis_facts: OptimizerIdentityRunCache[tuple[AnalysisFactContextKey, "StepFact"]] = field(
        default_factory=OptimizerIdentityRunCache
    )
    dependency_facts: OptimizerIdentityRunCache[frozenset[ServerPlanRefId]] = field(default_factory=OptimizerIdentityRunCache)
    ordered_sql_dependency_facts: OptimizerIdentityRunCache[frozenset[ServerPlanRefId]] = field(default_factory=OptimizerIdentityRunCache)
    scheduling_fingerprint_facts: OptimizerIdentityRunCache[SchedulingFingerprintFact] = field(default_factory=OptimizerIdentityRunCache)
    runtime_state_clean_by_fingerprint: OptimizerFingerprintSet = field(default_factory=OptimizerFingerprintSet)
    same_plan_coalesce_by_identity: OptimizerSamePlanCoalesceCache = field(default_factory=OptimizerSamePlanCoalesceCache)
    strategy_can_handle_by_identity: OptimizerStrategyIdentityCache = field(default_factory=OptimizerStrategyIdentityCache)
    verified_dependency_order_by_contract: OptimizerDependencyVerificationCache = field(
        default_factory=OptimizerDependencyVerificationCache
    )
    verified_dependency_order_by_identity: OptimizerDependencyVerificationIdentityCache = field(
        default_factory=OptimizerDependencyVerificationIdentityCache
    )
    adapted_sequence_by_identity: OptimizerAdaptedSequenceCache = field(default_factory=OptimizerAdaptedSequenceCache)
    adapted_step_by_identity: OptimizerAdaptedStepCache = field(default_factory=OptimizerAdaptedStepCache)
    counters: OptimizerCounterValues = field(default_factory=OptimizerCounterValues)
    counter_distinct_values: OptimizerDistinctValues = field(default_factory=OptimizerDistinctValues)

    @cached_pure_lazy(cache_args=("self",))
    def dependencies_for[T](
        self: OptimizerRunCache,
        step: ServerPlanStep[T],
    ) -> frozenset[ServerPlanRefId]:
        """Return dependency refs cached for this optimizer run."""
        dependencies = self.dependency_facts.get(step)
        cache_hit = dependencies is not None
        if dependencies is None:
            resolved_dependencies = step.dependencies_with_resolver(self.dependencies_for)
            dependencies = frozenset(ServerPlanRefId(dependency) for dependency in resolved_dependencies)
            self.dependency_facts.set(step, dependencies)
        counter = "step_dependency_cache_hits" if cache_hit else "step_dependency_cache_misses"
        self.inc_counter(counter)
        return dependencies

    @cached_pure_lazy(cache_args=("self",))
    def ordered_sql_dependencies_for[T](
        self: OptimizerRunCache,
        step: ServerPlanStep[T],
    ) -> frozenset[ServerPlanRefId]:
        """Return ordered-statement SQL dependencies for this optimizer run."""

        dependencies = self.ordered_sql_dependency_facts.get(step)
        cache_hit = dependencies is not None
        if dependencies is None:
            step_type = type(step)
            if (
                step_type.ordered_statement_sql_visible_dependencies is ServerPlanStep.ordered_statement_sql_visible_dependencies
                and step_type.sql_visible_dependencies is ServerPlanStep.sql_visible_dependencies
            ):
                ordering_only_refs = {
                    "__apply_sql_queue_auth",
                    "__apply_sql_session_context",
                }
                resolved_dependencies = self.dependencies_for(step)
                dependencies = frozenset(dependency for dependency in resolved_dependencies if str(dependency) not in ordering_only_refs)
            else:
                dependencies = frozenset(ServerPlanRefId(dependency) for dependency in step.ordered_statement_sql_visible_dependencies())
            self.ordered_sql_dependency_facts.set(step, dependencies)
        counter = "ordered_sql_dependency_cache_hits" if cache_hit else "ordered_sql_dependency_cache_misses"
        self.inc_counter(counter)
        return dependencies

    @cached_pure_lazy(cache_args=("self",))
    def scheduling_fingerprint_for[T](
        self: OptimizerRunCache,
        step: ServerPlanStep[T],
    ) -> tuple[object, ...] | None:
        """Return one scheduling fingerprint for this optimizer run."""

        fact = self.scheduling_fingerprint_facts.get(step)
        cache_hit = fact is not None
        if fact is None:
            fingerprint = step.scheduling_fingerprint_with_resolvers(
                self.dependencies_for,
                self.scheduling_fingerprint_for,
            )
            if fingerprint is None:
                fact = SchedulingFingerprintAbsent()
            else:
                fact = SchedulingFingerprintPresent(fingerprint)
            self.scheduling_fingerprint_facts.set(step, fact)
        counter = "scheduling_fingerprint_cache_hits" if cache_hit else "scheduling_fingerprint_cache_misses"
        self.inc_counter(counter)
        if isinstance(fact, SchedulingFingerprintAbsent):
            return None
        cached_fingerprint = fact.value
        assert isinstance(cached_fingerprint, tuple)
        return cached_fingerprint

    def inc_counter(self, name: str, amount: float = 1.0) -> None:
        """Increment a lightweight optimizer/executor profiling counter."""
        counter_name = OptimizerCounterName(name)
        self.counters[counter_name] = self.counters.get(counter_name, 0.0) + amount

    def mark_distinct(
        self,
        name: OptimizerCounterName,
        value: OptimizerDistinctIdentity,
    ) -> None:
        """Track distinct identities for non-cProfile benchmark diagnostics."""
        self.counter_distinct_values[name] = self.counter_distinct_values.get(
            name,
            frozenset(),
        ) | frozenset({value})

    def counter_snapshot(self) -> OptimizerCounterSnapshot:
        """Return current counters, including distinct-value set cardinalities."""
        snapshot = OptimizerCounterValues(self.counters)
        for name, values in self.counter_distinct_values.items():
            snapshot[name] = float(len(values))
        return OptimizerCounterSnapshot(tuple(snapshot.items()))

    def counter_delta(
        self,
        before: OptimizerCounterSnapshot,
    ) -> OptimizerCounterSnapshot:
        """Return counters accumulated since ``before``."""
        before_values = OptimizerCounterValues(before.entries)
        after_values = OptimizerCounterValues(self.counter_snapshot().entries)
        keys = set(before_values) | set(after_values)
        return OptimizerCounterSnapshot(
            tuple(
                (key, after_values.get(key, 0.0) - before_values.get(key, 0.0))
                for key in keys
                if after_values.get(key, 0.0) != before_values.get(key, 0.0)
            ),
        )

